\title{Distributed Bilevel Optimization with Dual Pruning for Resource-limited Clients}


\author{Mingyi Li, \and Xiao Zhang, \and Ruisheng Zheng, \and Hongjian Shi, \and Yuan Yuan, \and Xiuzhen Cheng, \and and Dongxiao Yu
\thanks{Mingyi Li, Xiao Zhang, Hongjian Shi, Xiuzhen Cheng and Dongxiao Yu are with the School of Computer Science and Technology, Shandong University, Qingdao 266237, China.\protect ~Email: limee@mail.sdu.edu.cn; xiaozhang@sdu.edu.cn; hongjian@mail.sdu.edu.cn; xzcheng@sdu.edu.cn; dxyu@sdu.edu.cn.}
\thanks{Ruisheng Zheng is with the School of Cyber Science and Technology, Shandong University, Qingdao 266237, China.\protect ~Email: rex7@mail.sdu.edu.cn.}
\thanks{Yuan Yuan is with the School of Software $\&$ Joint SDU-NTU Centre for Artificial Intelligence Research (C-FAIR), Shandong University, Jinan, 250000, China.\protect ~Email: yyuan@sdu.edu.cn.}}


\markboth{Journal of \LaTeX\ Class Files,~Vol.~14, No.~8, August~2021}
{Shell \MakeLowercase{\textit{et al.}}: A Sample Article Using IEEEtran.cls for IEEE Journals}

\IEEEpubid{0000--0000/00\$00.00~\copyright~2021 IEEE}



\maketitle

\begin{abstract}
With the development of large-scale models, traditional distributed bilevel optimization algorithms cannot be applied directly in low-resource clients. 


The key reason lies in the excessive computation involved in 

optimizing both the lower- and upper-level functions. 

Thus, we present the first resource-adaptive distributed bilevel optimization framework with a second-order free hypergradient estimator, which allows each client to optimize the submodels adapted to the available resources.

Due to the coupled influence of partial outer parameters $x$ and inner parameters $y$, it's challenging to theoretically analyze the upper bound regarding the globally averaged hypergradient for full model parameters. The error bound of inner parameter also needs to be reformulated since the local partial training.


The provable theorems show that both \textit{RABO} and \textit{RAFBO} can achieve an asymptotically optimal convergence rate of $\mathcal{O}(1/\sqrt{\mathcal{C}_x^*Q})$, which is dominated by the minimum coverage of the outer parameter $\mathcal{C}_x^*$. 
Extensive experiments on two different tasks 

demonstrate the effectiveness and computation efficiency of our proposed methods. 
\end{abstract}


\begin{IEEEkeywords}
Distributed bilevel optimization, Limited resources, Large-scale model, Heterogeneity, Convergence analysis
\end{IEEEkeywords}

Distributed bilevel optimization has emerged as a highly promising paradigm in collaboratively solving bilevel optimization. FedNest~\cite{conf/icml/fednest} is the first to focus on general nested problems and provides a convergence rate guarantee under the heterogeneity setting. And based on it, FedMBO~\cite{conf/icml/fedmbo} achieves the first linear speedup result. Considering the communication cost, AggITD~\cite{xiao2023communication} leverages the idea of iterative differentiation that computes the hypergradient through intermediate iterates of the lower-level updates on $y$, which achieves the same sample complexity as existing AID-based approaches while reducing the communication rounds. Further, SimFBO~\cite{yang2024simfbo} introduces an additional global quadratic programming and updates three sub-problem in clients simultaneously, thus per iteration only needs one communication round. Although ShroFBO~\cite{yang2024simfbo} considers the system-level heterogeneity, it claims that different computing capabilities lead to an unequal number of
local updates, which is different from the challenge that we consider. FedBiOAcc~\cite{li2024communication} leverages momentum-based variance reduction to achieve optimal convergence rate. Moreover, bilevel optimization has also been studied in other distributed settings, such as decentralized bilevel optimization~\cite{chen2023decentralized} and asynchronous bilevel optimization~\cite{jiaoasynchronous}.
However, existing distributed bilevel optimization algorithms require sufficient computation resources on clients, which cannot be applied in resource-limited scenarios.



\begin{algorithm}[t]
  \caption{Recourse-Adaptive Distributed Stochastic Bilevel Optimization(RABO)}
  \label{alg:rabo} 
  \begin{algorithmic}[1]
    \STATE {\bfseries Input:} number of clients $n$, initial point $(x_0, y_0)$, mask policy ${M}(\cdot, R_n)$
    \FOR{$q = 0,1, \ldots, Q-1$}



    \FOR{$i \in \left[n\right]$ in parallel}

    \STATE \begin{small}Generate mask $ m^i_{q,x}=\mathcal{M}(x_{q},R_i)$ , $m^i_{q,y}=\mathcal{M}(y_{q}, R_i)$
    \STATE Generate submodel $ x^i_{q}=x_{q}\odot m^i_{q,x}, y^i_{q,0}=y_{q}\odot m^i_{q,y}$\end{small}

    \FOR{epoch $t = 0,1, \ldots, T-1$}



    \STATE Compute $G_{q,t}^i=\nabla g_i(x^i_{q}, y^i_{q,t};\xi_{t}^{i})\odot m^i_{q,y}$
    \STATE $y^i_{q,t+1}=y^i_{q,t}-\beta G_{q,t}^i$
    \ENDFOR

    \STATE $G_{q}^i=\frac{y^i_{q,T}-y^i_{q,0}}{\beta}$

    \ENDFOR
    \FOR{parameters $k$ to $\mathcal{S}_{y}$ in $y$}
    \STATE Find $N_{q,y}^{k}=\{i:m_{q,y}^k=1\}$
    \STATE $\mathcal{C}_{q,y}^{k}=|N_{q,y}^{k}|$
    \IF{$\mathcal{C}_{q,y}^{k}=0$}
    \STATE Update $y_{q+1}^k= y_{q}^k$
    \ELSE
    \STATE $y_{q+1}^k = y_{q}^k-\beta\frac{1}{\mathcal{C}_{q,y}^{k}} \sum_{n\in N_{q,y}^{k}}G_{q}^{i,k}$

    \ENDIF
    \ENDFOR

    \FOR{$i \in \left[n\right]$ in parallel}
    \STATE Generate submodel $y^i_{q+1}=y_{q+1}\odot m^i_{q,y}$
    \STATE \colorbox{cyan!30}{Compute hypergradient $\mathcal{H}_q^i=\nabla f_i(x_q^i, y_{q+1}^i;\zeta)$}

    \ENDFOR

    \FOR{parameters $s$ to $\mathcal{S}_{x}$ in $x$}
    \STATE Find $N_{q,x}^{s}=\{i:m_{q,x}^s=1\}$
    \STATE $\mathcal{C}_{q,x}^{s}=|N_{q,x}^{s}|$
    \IF{$\mathcal{C}_{q,x}^{s}=0$}
    \STATE Update $x_{q+1}^s= x_{q}^s$
    \ELSE
    \STATE $x_{q+1}^s = x_q^s- \alpha \frac{1}{\mathcal{C}_{q,x}^{s}} \sum_{n\in N_{q,x}^{s}} \mathcal{H}_q^i$

    \ENDIF
    \ENDFOR
    \ENDFOR
  \end{algorithmic}
\end{algorithm}

The \textbf{Recourse-Adaptive Distributed Stochastic Bilevel Optimization (RABO)} algorithm is designed to solve bilevel optimization problems in a distributed setting, particularly for models with client heterogeneity and resource constraints. As shown in Algorithm~\ref{alg:rabo}, the server sends the latest full model to all clients, each client generates an adaptive submodel based on their resources. After the inner and outer partial parameters nested local updates, the server aggregates updates for each parameter. The above process will repeat until the model converges. The detailed algorithm proceeds in the $q$-th global iteration as follows:

\textbf{Local Submodel Generation.} 
At each global iteration \( q \), the server sends the latest global model $(x_q, y_q)$ to clients, each client uses the resource-adaptive mask policy $\mathcal{M}(\cdot, R_i)$ to generate masks, where $R_i$ is the resource constrains of the client $i$.
\begin{equation}
    m^i_{q,x}=\mathcal{M}(x_{q},R_i),\quad m^i_{q,y}=\mathcal{M}(y_{q}, R_i).
\end{equation}
The mask $m^i_{q,x}\in\{0,1\}^{d_1}$,  $m^i_{q,y}\in\{0,1\}^{d_2}$, each element denotes whether the parameter is in the local submodel or not. 
According to the mask, we use a structured pruning method to construct the corresponding submodel for further training.
\begin{equation}
    x^i_{q} = x_q \odot m^i_{q,x},\quad  y^i_{q,0} = y_q \odot m^i_{q,y},
\end{equation}











where $\odot$ operation denotes the structured pruning. Considering the heterogeneous dynamics of client resources, masks can be changed in different global iterations. Overall, we define the full inner parameters as $\mathcal{S}_{y}$, full outer parameters as $\mathcal{S}_{x}$ and trained ones as $\mathcal{K}_{q,y}, \mathcal{K}_{q,x}$.
Here, considering the actual application, we can determine whether to apply the mask for both inner and outer parameters or not. For example, when applying \textit{RABO} to hyper-parameter optimization, each client must optimize the full hyper-parameters $x$, thus, we can only prune inner parameters to match the local resource.

\textbf{Inner Submodel update.}
Each client calculates the inner gradient  $G_{q,t}^i$ based on the inner function $g_i(x^i_{q}, y^i_{q,t})$ and updates the inner submodel with $T$ epochs: 
\begin{equation}
    G_{q,t}^i = \nabla g_i(x^i_{q}, y^i_{q,t}; \xi_t^i) \odot m^i_{q,y},\quad y^i_{q,t+1} = y^i_{q,t} - \beta G_{q,t}^i   .
\end{equation}
After completing the local updates, compute the gradient \( G_q^i \) for each client \( i \) as:
$G_q^i = (y^i_{q,T} - y^i_{q,0})/\beta$.
This gradient is used for the global inner optimization step.

\textbf{Inner Parameter-wise Gradient Aggregation}
For each parameter $k \in \mathcal{S}_y$ in $y$, identify the set of clients $N_{q,y}^k=\{ i:m_{q,y}^k=1\}$ that contribute to the update of this parameter, the number of these clients denotes as $\mathcal{C}_{q,y}^k$. The aggregated gradient is then used to update $y_{q+1}^k$ as:
\begin{equation}
y_{q+1}^k = y_q^k - \beta \frac{1}{\mathcal{C}_{q,y}^k} \sum_{i \in N_{q,y}^k} G_q^{i,k},
\end{equation}
where $\beta$ is the inner learning rate. If no clients contribute to a particular parameter, it remains unchanged. Thus, we gain the updated inner parameter $y_{q+1}$ to approximate the minimizer $y^*(x)$ of lower-level problem.

\textbf{Hypergradient Calculation.} 
The server broadcasts the updated $y_{q+1}$, and the clients use it to calculate the hypergradient.
\begin{align}
\nabla f_i(x_q^i, y_{q+1}^i) = &\nabla_x f_i(x_q^i, y_{q+1}^i)- \nabla^2_{xy} g_i(x_q^i, y_{q+1}^i)\\
&[\nabla^2_{yy} g_i(x_q^i, y_{q+1}^i)]^{-1}\nabla_y f_i(x_q^i, y_{q+1}^i).\nonumber\label{surrogate_f}
\end{align}

Due to the submodels being trained within each client, 

the dimensions of parameters are much smaller than the full model, which reduces the computational burden. 


\textbf{Outer Parameter-wise Gradient Aggregation.} We use the same parameter-wise gradient aggregation as inner update to compute the aggregated hypergradients and update the outer parameters. 
\begin{equation}
 x_{q+1}^s = x_q^s - \alpha \frac{1}{\mathcal{C}_{q,x}^s} \sum_{i \in N_{q,x}^s} \nabla f_i(x_q^i, y_{q+1}^i; \zeta), 
\end{equation}
where \( \alpha \) is the outer learning rate, and \( \mathcal{C}_{q,x}^s \) denotes the number of clients contributing to the update.



\begin{algorithm}[t]
  \caption{\colorbox{cyan!30}{Second-Free Hypergradient Approximator}}
  \label{alg:approximation} 
  \begin{algorithmic}[1]
    \STATE {\bfseries Input:} submodel $x_q^i, y_{q+1}^i$, perturbation vector $\mu$
    \STATE {\bfseries Output:} Approximated local hypergradient $\mathcal{H}_i$

    \STATE Calculate and sample coordinate set $\mathcal{P}_{q}^i$ of trained submodel $x_q^i$.
    \FOR{$\textbf{e}_p\in\mathcal{P}_{q}^i$}
    \STATE $\delta(x_q,\textbf{e}_p, \xi)=\frac{\nabla_y g(x_q^i+\mu\textbf{e}_p,y_{q+1}^i, \xi)-\nabla_y g(x_q^i,y_{q+1}^i, \xi)}{\mu}$
    \ENDFOR
    \STATE $\mathcal{H}_i=\hat{\nabla} f_i(x_q,y_{q+1}, \zeta)=\nabla_x f_i(x_q^i,y^i_{q+1}, \zeta)+\sum_{\mathcal{P}_{q}^i}\left \langle\delta(x_q,\textbf{e}_p, \xi),\nabla_yf_i(x_q^i,y^i_{q+1}, \zeta)\right \rangle \textbf{e}_p $
  \end{algorithmic}
\end{algorithm}

\label{sec:rafbo}


In this section, we give a further partial approximation method for the local hypergradient to avoid
computing the Jacobian and Hessian matrix, as described in Algorithm \ref{alg:approximation}. Since this method is second-order free, we call the algorithm with the hypergradient estimator as \textit{RAFBO}.

Returning to the explicit function of hypergradient,
\begin{align}
    \nabla\Phi(x) = \nabla_x f(x,y^*(x))+\mathcal{J}^*(x)^\top\nabla_y f(x,y^*(x)),
\end{align}
where $\mathcal{J}^*(x)=\frac{\partial y*(x)}{\partial x}$. Following ~\cite{pzobo}, we use the idea of finite differences to approximate the $\mathcal{J}^*(x)$ directly, which avoids calculating the $\nabla^2_{xy} g_i(x_q^i, y_{q+1}^i)$ and $[\nabla^2_{yy} g_i(x_q^i, y_{q+1}^i)]^{-1}$. Inspired by the ~\cite{lian2016comprehensive, liu2020primer}, we choose the deterministic coordinate-wise perturbations. First we calculate and sample the coordinate set \( \mathcal{P}_q^i \) for the trained submodel \( x_q^i \), which consists of the directions along which the perturbations will be applied. Compared to the existing finite differences method, we use the deterministic coordinate-wise perturbations of model instead of random perturbations, which is more accurate and time efficient~\cite{chen2024deepzero}.

It is worth noting that due to the construction of submodel, the size of coordinate set is smaller than the original full model, which further reduces the computation. 

For each coordinate \( \textbf{e}_p \in \mathcal{P}_q^i \), we apply a perturbation \( \mu \textbf{e}_p \) to the submodel \( x_q^i \) and compute the difference in the gradient of the loss function with respect to \( y \):
\begin{equation}
\scalebox{0.9}{$
\begin{aligned}
\hat{\mathcal{J}}(x_q, \textbf{e}_p, \xi) = \frac{\nabla_y g(x_q^i + \mu \textbf{e}_p, y_{q+1}^i, \xi) - \nabla_y g(x_q^i, y_{q+1}^i, \xi)}{\mu} \textbf{e}_p,
\end{aligned}
$}    
\end{equation} 
where $\mu>0$ is the smoothing parameter. Once the finite differences are computed for all coordinates in \( \mathcal{P}_q^i \), the local hypergradient is approximated as:
\begin{equation}
\scalebox{0.9}{$
\begin{aligned}
  &\hat{\nabla} f_i(x_q,y_{q+1}, \zeta)\\
  &=\nabla_x f_i(x_q^i,y^i_{q+1}, \zeta)+\sum_{\mathcal{P}_{q}^i} \hat{\mathcal{J}}(x_q,\textbf{e}_p, \xi)^\top\nabla_yf_i(x_q^i,y^i_{q+1}, \zeta)\nonumber\\
  &=\nabla_x f_i(x_q^i,y^i_{q+1}, \zeta)+\sum_{\mathcal{P}_{q}^i}\left \langle\delta(x_q,\textbf{e}_p, \xi),\nabla_yf_i(x_q^i,y^i_{q+1}, \zeta)\right \rangle \textbf{e}_p \nonumber 
\end{aligned}
$}    
\end{equation}  
From the perspective of computational efficiency, we use the vector-vector dot product instead of Jacobian-vector product, where $\delta(x_q,\textbf{e}_p, \xi)=(\nabla_y g(x_q^i+\mu\textbf{e}_p,y_{q+1}^i, \xi)-\nabla_y g(x_q^i,y_{q+1}^i, \xi))/\mu\in \mathbb{R}^{d_2}$, $\left\langle \cdot, \cdot \right\rangle$ denotes the inner product. 


By embedding this approximation to the proposed \textit{RABO}, we reduce the computational complexity of calculating the hypergradient while maintaining a reasonable level of accuracy for the parameter updates in the outer loop.

Let $z=(x,y)\in \mathbb{R}^{d_1+d_2}$ denote all parameters throughout the following definitions and assumptions.

\begin{definition}
    Function $h$ is $L$-Lipschitz continuous if
    \begin{equation}
    \|h(z_1)-h(z_2)\|\leq L\|z_1-z_2\|\quad \forall z_1, z_2.    
    \end{equation}
\end{definition}

\begin{definition}
    The solution $z$ is $\epsilon$-accurate stationary point of the objective function $\Phi(z)$ if $\mathbb{E}\|\nabla\Phi(z)\|^2\leq \epsilon$, where $z$ is the output of an algorithm.
\end{definition}

\begin{definition}
(Minimum covering clients). The minimum clients trained the i-th parameter across all submodels of inner parameters $y$ or outer parameters $x$ throughout all global iterations can be defined as:
\begin{align}
&\mathcal{C}^*_x= \min\limits_{q,s} \mathcal{C}_{q,x}^s, s \in \mathcal{K}_{q,x}, \forall q,\\
&\mathcal{C}^*_y= \min\limits_{q,k} \mathcal{C}_{q,y}^k, k \in \mathcal{K}_{q,y}, \forall q,
\end{align}
where $\mathcal{C}_{q,x}^s$ is the number of the client that train the $i$-th parameter of outer parameters $x$ in the global iteration $q$ and $\mathcal{C}_{q,y}^k$ is related to inner parameters $y$.
\end{definition}

\begin{assumption}(Non-convex-strongly-convex).
\label{assum:convex}
For all $i\in [n]$, $f_i(x,y)$ is possibly non-convex and $g_i(x,y)$ is $\mu_g$-strongly convex in $y$ for any fixed $x\in\mathbb{R}^{d_1}$.
\end{assumption}

\begin{assumption}(Lipshitz continuous).
\label{assum:lipschitz}
For all $i\in[n]$, $f_i(z)$, $\nabla f_i(z)$, $\nabla g_i(z)$, $\nabla^2 g_i(z)$ are $\ell_{f,0}$, $\ell_{f,1}$, $\ell_{g,1}$, $\ell_{g,2}$-Lipshitz continuous, respectively.
\end{assumption}


\begin{assumption}\label{assum:sto_sample}(Unbiased estimators).
For all $i\in [n]:$
$\nabla f_i(z;\zeta)$, $\nabla g_i(z;\xi)$ are unbiased estimators of $\nabla f_i(z)$, $\nabla g_i(z)$, there exist constants $\sigma_f^2$, $\sigma^2_{g}$, such that 
\begin{align}
    &\mathbb{E}_{\zeta}\left\|\nabla f_i(z;\zeta)-\nabla f_i(z)\right\|^2\leq \sigma_f^2,
    \\
    &\mathbb{E}_{\xi}\left\|\nabla g_i(z;\xi)-\nabla g_i(z)\right\|^2\leq \sigma_{g}^2,



\end{align}
\end{assumption}

\begin{assumption}\label{assum:hetero}
     (Bounded data heterogeneity level). For all $i\in[n]$: there exist constants $\delta^2_f$ and $\delta^2_g$, such that:
     \begin{align}
         \mathbb{E}\left\|\nabla f_i(z)-\nabla f(z)\right\|^2]\leq \delta^2_f,\\
         \mathbb{E}\left\|\nabla g_i(z)-\nabla g(z)\right\|^2]\leq \delta^2_g.        
     \end{align}
\end{assumption}

\begin{assumption}\label{assum:mask}
    (Bounded noise induced from submodel). The deviation of the submodel in client $n$ from the original parameters for every global iteration $q$ is limited by $w_1,w_2\in[0,1)$:
\begin{align}
        \|x_q-x_q\odot m_{q,x}^i\|^2 &\leq w_1^2\|x_q\|^2,\\
        \|y_q-y_q\odot m_{q,y}^i\|^2 &\leq w_2^2\|y_q\|^2.
\end{align}
\end{assumption}

The above assumptions are commonly used in previous works. Assumption~\ref{assum:convex} supposes the non-convex-strongly-convex bilevel optimization problems, which guarantee the existence of the hypergradient $\nabla\Phi(x)$~\cite{kwon2023fully,FdeHBO}. 
Assumption~\ref{assum:lipschitz} imposes the levels of Lipschitz smoothness, which is a standard assumption in distributed bilevel optimization~\cite{xiao2023communication,yang2024simfbo}.
Assumption~\ref{assum:sto_sample} shows the stochastic estimators are unbiased with bounded variances, which is widely used in stochastic optimization~\cite{tarzanagh2022fednest,conf/icml/fedmbo}. 
Assumption~\ref{assum:hetero} controls the difference between local and global gradient, which is common in traditional federated learning without bilevel optimization~\cite{li2019convergence,yuan2022convergence}.
Assumption~\ref{assum:mask} states the influence of the submodel, as also adopted by other studies about model pruning~\cite{wang2023theoretical,zhou2024every}.

In order to analyze the convergence rate of our proposed recourse-adaptive distributed stochastic bilevel optimization algorithm, we firstly state some preliminary lemmas as follows:

\begin{lemma}

Under Assumptions 1 and 2, we have 
\begin{align}
    ||\nabla \Phi(x_1) -\nabla \Phi(x_2)||&\leq L_f ||x_1 - x_2||,\label{eq:f_lip}\\
    ||y^*(x_1)-y^*(x_2)||&\leq L_y ||x_1-x_2||,
\end{align}
where 
\begin{align}
    L_f :=& l_{f,1}+\frac{l_{g,1}(l_{f,1}+M_f)}{\mu_g}+\frac{l_{f,0}}{\mu_g}(l_{g,2}+\frac{l_{g,1}l_{g,2}}{\mu_g}), \nonumber
    \\
    L_y :=& \frac{l_{g,1}}{\mu_g}.\nonumber
\end{align}
For all $i\in [n]$, we have 
\begin{align}
    ||\nabla f_i(x_1, y)-\nabla f_i(x_1,y^*(x_1))|| &\leq M_f ||y-y^*(x_1)||,\\
    ||\nabla f_i(x_1,y)-\nabla f_i(x_2,y)|| &\leq M_f||x_1-x_2||,
\end{align}
where the constant $M_f$ is given by 
\begin{align}
    M_f:=l_{f,1}+\frac{l_{g,1}l_{f,1}}{\mu_g}+\frac{l_{f,0}}{\mu_g}(l_{g,2}+\frac{l_{g,1}l_{g,2}}{\mu_g})\nonumber
\end{align}
\end{lemma}

\begin{lemma} Under Assumptions 1 and 2, we have 
\begin{align}\mathbb{E}\|\nabla f^s_n(x_{q}^n,y_{q+1}^n)-\nabla f^s_n(x_{q},y_{q+1})\|^2\leq \mathcal{E}_h\end{align}
\end{lemma}
\begin{proof}
\begin{align*}
    &\mathbb{E}\|\nabla f^s_n(x_{q}^n,y_{q+1}^n)-\nabla f^s_n(x_{q},y_{q+1})\|^2\\
    \leq&2\mathbb{E}\|\nabla f^s_n(x_{q}^n,y_{q+1}^n)-\nabla f^s_n(x_{q},y_{q+1}^n)\|^2\\&\quad+2\mathbb{E}\|\nabla f^s_n(x_{q},y_{q+1}^n)-\nabla f^s_n(x_{q},y_{q+1})\|^2\\
    \leq &2 M_f^2\|x_q^n-x_q\|^2+2M_f^2\|y_{q+1}^n-y_{q+1}\|^2 \\
    \leq &2M_f^2 w_1^2 \|x_q\|^2+2M_f^2 w_2^2 \|y_{q+1}\|^2
\end{align*}
\end{proof} 

\begin{lemma}\label{hyper-gradient estimation}
(Hypergradient estimation error.) Suppose that Assumption~\ref{assum:lipschitz} holds. The hypergradient estimation error can be bounded as 
\begin{align}
    \|\hat{\nabla} f_i(x_q,y_{q+1},\zeta)- \nabla f_i(x_q,y_{q+1},\zeta)\|^2\leq \sigma_{\mathcal{J}}^2.
\end{align}
where $\sigma_{\mathcal{J}}^2 = P^{*2}l_{g,1}^2\mu^2l_{f,0}^2/4$, $P^*=\max\limits_{i}|\mathcal{P}_q^i|,i\in[n], \forall q.$
\end{lemma}

\begin{theorem}\label{convergence1}
(Convergence result of RABO) Let all assumptions hold, suppose the learning rates satisfy these conditions
\begin{equation*}\label{}
   \left\{\begin{array}{l c l}
    \alpha\leq\frac{1}{L_f+4M_f}\\
    \beta\leq min\{\frac{1}{2l_{g,1}}, \frac{1}{\mu_g}\} \nonumber\\
     \beta\geq\frac{1}{\mu_g}-\frac{1}{2\alpha L_yM_f\mu_g}\nonumber
    \end{array}\right.
\end{equation*}
Then for all $Q\geq1$, we have
\begin{align}
     \frac{1}{Q}\sum_{q=1}^Q&\sum_{s\in \mathcal{K}_{q,x}}\mathbb{E}\|\nabla \Phi^s(x_{q})\|^2\\
     \leq &\frac{2\Delta}{\alpha Q}+\frac{2N\hat{\alpha}_1}{\alpha\mathcal{C}_x^*}\sigma_f^2+\frac{2N\hat{\alpha}_1}{\alpha\mathcal{C}_x^*}\delta^2_f\nonumber\\
     &+\frac{4N\hat{\alpha}_1}{\alpha\mathcal{C}_x^*}\frac{1}{Q}\sum_{q=1}^Q(M_f^2 w_1^2 \|x_q\|^2+M_f^2 w_2^2 \|y_{q+1}\|^2)\nonumber\\
     &+(4M_f^2+\frac{4M_f}{\alpha L_y})\frac{4\beta^2NT(\sigma_{g}^2+\delta_{g}^2)}{\mathcal{C}^{*}_{y}}\nonumber
\end{align}
where $\Delta=\mathbb{E}\|V_{Q+1}\|-\mathbb{E}\| V_{1}\|$, $\hat{\alpha}_1=2L_f\alpha^2+8M_f\alpha^2$
\end{theorem}
Theorem~\ref{convergence1} shows the convergence rate of the proposed algorithm \textit{RABO} by presenting the upper bound regarding the globally averaged hypergradient for all model parameters.
\begin{remark}
(Impact of different key factors). From the Theorem~\ref{convergence1}, we
analyze the impact of key factors on the \textit{RABO} convergence rate:
\begin{itemize}
    \item \textbf{Impact of noise induced from mask.} As the Theorem~\ref{convergence1} shows, 
    due to the submodel training strategy, we additionally introduce the term $\mathcal{O}(\frac{\alpha}{\mathcal{C}_x^*}\frac{1}{Q}\sum_{q=1}^QM_f^2 w_1^2 \|x_q\|^2+\frac{\alpha}{\mathcal{C}_x^*}\frac{1}{Q}\sum_{q=1}^QM_f^2 w_2^2 \|y_{q+1}\|^2)$ of the hypergradient bound, which is proportional to the noise $w_1$ and $w_2$. When $w_1$ and $w_2$ are small, the convergence rate is faster under the same $\mathcal{C}^*_x$.

    Notably, if the client trains the full parameter $x$ and $y$, where $\mathcal{K}_{q,x}=\mathcal{S}_x, \mathcal{K}_{q,y}=\mathcal{S}_y$ and $m_x^i=1, m_y^i=1$, then $w_1=0, w_2=0$, there is also no additional noise generated.
    \item \textbf{Impact of data heterogeneity $\delta_f$ and $\delta_g$.} As previously described, data distribution in real-world settings is inherently non-IID. This heterogeneity plays a critical role in determining the convergence behavior of the model, as shown in Theorem~\ref{convergence1}. Here we make a detailed distinction between the effects of data heterogeneity on inner and outer functions and denote as $\delta_f$ and $\delta_g$. 

    Specifically, larger $\delta_f$ and $\delta_g$ indicate a higher degree of data heterogeneity, which adversely affects convergence by slowing it down. In contrast, when the data distribution is IID, such that $\delta_f = 0, \delta_g=0$, the impact of heterogeneity vanishes.
\end{itemize}
\end{remark}

Next, by specifying the parameters $\alpha$ and $\beta$, we can obtain the following convergence result.
\begin{corollary}\label{corollary1}
(Convergence rate of RABO) Let all assumptions hold. Supposing  $\alpha\leq \sqrt{C_x^*/Q}$, and $\beta \leq \frac{1}{NTQ}$, we can get
\begin{align}
    &\frac{1}{Q}\sum_{q=1}^Q\sum_{s\in \mathcal{K}_{q,x}}\mathbb{E}\|\nabla \Phi^s(x_{q})\|^2\\&\leq \mathcal{O}(\frac{1}{\sqrt{\mathcal{C}_x^*Q}}+\frac{1}{NTQ^2\mathcal{C}^{*}_{y}}+\frac{1}{NTQ^{1.5}\sqrt{\mathcal{C}_x^*}\mathcal{C}^{*}_{y}})\nonumber
\end{align}
\end{corollary}
\begin{remark}
   Corollary~\ref{corollary1} shows that the proposed resource-adaptive distributed bilevel optimization algorithm \textit{RABO} achieves a convergence rate $\mathcal{O}(\frac{1}{\sqrt{\mathcal{C}_x^*Q}})$. It demonstrates that for any local inner update epoch $T$, once choosing the proper learning rate $\alpha$ and $\beta$, \textit{RABO} converges with a sub-linear rate and has a linear speedup with respect to the minimum covering clients of outer parameter $\mathcal{C}_x^*$, which denotes the minimal number of clients that train specific partial outer parameters.
   When $\mathcal{C}_x^*=N$, all outer parameters are trained by all clients in every global iteration, the convergence rate of \textit{RABO} achieves $\mathcal{O}(\frac{1}{\sqrt{NQ}})$, which is identical to the linear speedup convergence rate of distributed bilevel optimizaiton algorithm \textit{FedMBO}~\cite{conf/icml/fedmbo}. 

   Notably, the definition of $\nabla\Phi(x)$ is under the condition of $y=y^*(x)$. Thus the inner submodel training will not dominate the convergence. But from lemma~\ref{lemma:error_inner} and Corollary~\ref{corollary1}, we can find that training the partial inner parameter also influences the convergence regarding the minimum covering clients of inner parameter $\mathcal{C}_y^*$. As with $\mathcal{C}_x^*$, it means inner parameters can be trained by at least $\mathcal{C}_y^*$ clients in each global iteration. As $\mathcal{C}_y^*$ increases while fixing other settings, the more frequently the model can be trained, thus the model can converge faster.
\end{remark}

\begin{theorem}\label{convergence2}
(Convergence result of RAFBO) Let all assumptions hold. Supposing $\alpha\leq \sqrt{\mathcal{C}_x^*/Q}$, $\beta \leq \frac{1}{NTQ}$, we can get
\begin{align}
     \frac{1}{Q}\sum_{q=1}^Q&\sum_{s\in \mathcal{K}_{q,x}}\mathbb{E}\|\nabla \Phi^s(x_{q})\|^2\\
     \leq& \mathcal{O}(\frac{\Delta}{\sqrt{\mathcal{C}_x^*Q}}+\frac{\sigma_{\mathcal{J}}^2+\sigma_f^2+\delta^2_f}{\sqrt{\mathcal{C}_x^*Q}}+\frac{w_1A_1+w_2A_2}{\sqrt{\mathcal{C}_x^*Q}}\nonumber\\
     &+\frac{\sigma_{g}^2+\delta_{g}^2}{NTQ^{1.5}\sqrt{\mathcal{C}_x^*}\mathcal{C}^{*}_{y}})\nonumber
\end{align}
where $\Delta=\mathbb{E}\|V_{Q+1}\|-\mathbb{E}\| V_{1}\|$, $A_1=\frac{1}{Q}\sum_{q=1}^Q\|x_q\|^2$, $A_2=\frac{1}{Q}\sum_{q=1}^Q\|y_{q+1}\|^2$.
\end{theorem}
\begin{remark}
Compared to the original algorithm \textit{RABO}, the bound of averaged global hypergradient only has one additional term $\mathcal{O}(\frac{\sigma_{\mathcal{J}}^2}{\sqrt{\mathcal{C}_x^*Q}})$, which is introduced by the partial hypergradient approximation according to Lemma~\ref{hyper-gradient estimation}. It has the same order $\mathcal{O}(\frac{1}{\sqrt{\mathcal{C}_x^*Q}})$ as the dominant term, and the total convergence rate is identical to \textit{RABO}. The approximation is designed to reduce computational memory without sacrificing the effectiveness of the optimization process. The theoretical results further show that the convergence rate of full model is not significantly altered by the approximation.
\end{remark}

In this part, we provide concrete proofs and analyzes for
the important lemma and theorem we have mentioned.
\begin{lemma}\label{lemma:error_inner}
(Inner error bound). Let all assumptions hold and $y^*(x_q)=\arg\min\limits_y \frac{1}{N}\sum_{i=1}^N g_i(x_q,y)$, $\beta\leq1/2l_{g,1}$, we have,
 \begin{align}
     \mathbb{E}&\|y_{q+1}-y^*(x_q)\|^2\\ &\leq(1-\beta\mu_g)\mathbb{E}\|y_{q}-y^*(x_q)\|^2+\frac{4NT\beta^2}{\mathcal{C}_y^*}(\sigma_{g}^2+\delta_{g}^2)\nonumber
    \end{align}
\end{lemma}
\begin{proof}
\begin{align}
    &\mathbb{E} \left\|y_{q+1}-y^*(x_q)\right\|^2
    \nonumber
    \\
    =&\sum_{k\in \mathcal{K}_{q,y}}\mathbb{E}\|y_{q+1}^k-y^*(x_q)^k\|^2 
    \nonumber 
    \\
    =& \sum_{k\in \mathcal{K}_{q,y}}\mathbb{E}\|y_{q}^k-\frac{1}{\mathcal{C}^{s}_{q,y}}\sum_{j\in N^{s}_{q,y}}\sum_{t=1}^T\beta \nabla_y g^k_j(x_{q}^j,y_{q,t}^j,\xi_t^j)-y^*(x_q)^k\|^2 
    \nonumber
    \\
    =&\sum_{k\in \mathcal{K}_{q,y}}\mathbb{E}\left\|y_{q}^k-y^*(x_q)^k\right\|^2\nonumber\\&-2\beta\sum_{k\in \mathcal{K}_{q,y}}\mathbb{E}\langle \frac{1}{\mathcal{C}^{s}_{q,y}}\sum_{j\in N^{s}_{q,y}}\sum_{t=1}^T \nabla_y g^k_j(x_{q}^j,y_{q,t}^j,\xi_t^j),\nonumber\\&\quad y_{q}^k-y^*(x_q)^k\rangle\nonumber\\
    &+\beta^2\sum_{k\in \mathcal{K}_{q,y}}\mathbb{E}\|\frac{1}{\mathcal{C}^{s}_{q,y}}\sum_{j\in N^{s}_{q,y}}\sum_{t=1}^T \nabla_y g^k_j(x_{q}^j,y_{q,t}^j,\xi_t^j)\|^2
    \nonumber
    \\
    \leq& (1-\beta\mu_g)\sum_{k\in \mathcal{K}_{q,y}}\left\|y_{q}^k-y^*(x_q)^k\right\|^2\label{lemma:bounded-gradient}\\&-2\beta\frac{NT}{\mathcal{C}^*} \sum_{k\in \mathcal{K}_{q,y}}\mathbb{E}\left[g(x_q^k,y_{q,t}^k)-g(x_q^k,y^*(x_q)^k)\right]\nonumber\\
    &+\beta^2\sum_{k\in \mathcal{K}_{q,y}}\mathbb{E}\|\frac{1}{\mathcal{C}^{s}_{q,y}}\sum_{j\in N^{s}_{q,y}}\sum_{t=1}^T \nabla_y g^k_j(x_{q}^j,y_{q,t}^j,\xi_t^j)\|^2\nonumber
\end{align}
To bound the last term in Eq.~\ref{lemma:bounded-gradient}, we have
\begin{align}
    &\sum_{k\in \mathcal{K}_{q,y}}\mathbb{E}\|\frac{1}{\mathcal{C}^{s}_{q,y}}\sum_{j\in N^{s}_{q,y}}\sum_{t=1}^T \nabla_y g^k_j(x_{q}^j,y_{q,t}^j,\xi_t^j)\|^2
    \nonumber
    \\
    =&\sum_{k\in \mathcal{K}_{q,y}}\mathbb{E}\|\frac{1}{\mathcal{C}^{s}_{q,y}}\sum_{j\in N^{s}_{q,y}}\sum_{t=1}^T[ \nabla_y g^k_j(x_{q}^j,y_{q,t}^j,\xi_t^j)\nonumber\\&-\nabla_y g^k_j(x_{q}^j,y^*(x_{q}),\xi_t^j)+\nabla_y g^k_j(x_{q}^j,y^*(x_{q}),\xi_t^j)]\|^2
    \nonumber






    \\
    \leq& \frac{2}{\mathcal{C}^{s}_{q,y}}\sum_{j\in N^{s}_{q,y}}\sum_{t=1}^T\sum_{k\in \mathcal{K}_{q,y}}\mathbb{E}\|\nabla_y g^k_j(x_{q}^j,y_{q,t}^j,\xi_t^j)\nonumber\\
    &-\nabla_y g^k_j(x_{q}^j,y^*(x_{q}),\xi_t^j)\|^2\nonumber\\
    &+2\sum_{k\in \mathcal{K}_{q,y}}\mathbb{E}\|\frac{1}{\mathcal{C}^{s}_{q,y}}\sum_{j\in N^{s}_{q,y}}\sum_{t=1}^T\left[\nabla_y g^k_j(x_{q}^j,y^*(x_{q}),\xi_t^j)\right]\|^2
    \nonumber
    \\
    \leq& \frac{4l_{g,1}}{\mathcal{C}^{s}_{q,y}}\sum_{j\in N^{s}_{q,y}}\sum_{t=1}^T\sum_{k\in \mathcal{K}_{q,y}}\mathbb{E}[g^k_j(x_{q}^j,y_{q,t}^j,\xi_t^j)-g^k_j(x_{q}^j,y^*(x_{q}),\xi_t^j)\nonumber\\
    &-\langle \nabla_y g^k_j(x_{q}^j,y^*(x_{q}),\xi_t^j),y_{q,t}^j-y^{*}(x^q)\rangle]
    \nonumber
    \\
    &+2\sum_{k\in \mathcal{K}_{q,y}}\mathbb{E}\|\frac{1}{\mathcal{C}^{s}_{q,y}}\sum_{j\in N^{s}_{q,y}}\sum_{t=1}^T[\nabla_y g^k_j(x_{q}^j,y^*(x_{q}),\xi_t^j)]\|^2
    \nonumber
    \\=&4l_{g,1}\frac{NT}{\mathcal{C}^{*}_{y}}\sum_{k\in \mathcal{K}_{q,y}}\mathbb{E}\left[g\left(x^k,y^{k,t}\right)-g\left(x^k,y^*(x^k)\right)\right]\label{lemma:gradient-y*}\\
    &+2\sum_{k\in \mathcal{K}_{q,y}}\mathbb{E}\|\frac{1}{\mathcal{C}^{s}_{q,y}}\sum_{j\in N^{s}_{q,y}}\sum_{t=1}^T[\nabla_y g^k_j(x_{q}^j,y^*(x_{q}),\xi_t^j)]\|^2\nonumber
\end{align}
To bound the last term in Eq.~\ref{lemma:gradient-y*}, we have
\begin{align}
    &\sum_{k\in \mathcal{K}_{q,y}}\mathbb{E}\|\frac{1}{\mathcal{C}^{s}_{q,y}}\sum_{j\in N^{s}_{q,y}}\sum_{t=1}^T\left[\nabla_y g^k_j(x_{q}^j,y^*(x_{q}),\xi_t^j)\right]\|^2
    \nonumber
    \\



    \leq&\frac{2}{\mathcal{C}^{s}_{q,y}}\sum_{j\in N^{s}_{q,y}}\sum_{t=1}^T\sum_{k\in \mathcal{K}_{q,y}}\mathbb{E}\|\nabla_y g^k_j(x_{q}^j,y^*(x_{q}),\xi_t^j)\nonumber\\&-\nabla_y g^k_j(x_{q}^j,y^*(x_{q}))\|^2
    \nonumber
    \\
    &+\frac{2}{\mathcal{C}^{s}_{q,y}}\sum_{j\in N^{s}_{q,y}}\sum_{t=1}^T\sum_{k\in \mathcal{K}_{q,y}}\mathbb{E}\|\nabla_y g^k_j(x_{q}^j,y^*(x_{q}))\nonumber\\&-\nabla_y g\left(x_{q},y^*(x_{q})\right)\|^2\nonumber\\
    \leq& \frac{2NT(\sigma_{g}^2+\delta_{g}^2)}{\mathcal{C}^{*}_{y}}
    \nonumber
\end{align}
Thus, we can gain that
\begin{align}
    &\mathbb{E} \left\|y_{q+1}-y^*(x_q)\right\|^2
    \nonumber
    \\
    \leq& (1-\beta\mu_g)\sum_{k\in \mathcal{K}_{q,y}}\left\|y_{q}^k-y^*(x_q)^k\right\|^2\nonumber\\&-2\beta\frac{NT}{\mathcal{C}^*} \sum_{k\in \mathcal{K}_{q,y}}\mathbb{E}\left[g(x_q^k,y_{q,t}^k)-g(x_q^k,y^*(x_q)^k)\right]\nonumber\\&+\beta^2\sum_{k\in \mathcal{K}_{q,y}}\mathbb{E}\|\frac{1}{\mathcal{C}^{s}_{q,y}}\sum_{j\in N^{s}_{q,y}}\sum_{t=1}^T \nabla_y g^k_j(x_{q}^j,y_{q,t}^j,\xi_t^j)\|^2
    \nonumber
    \\
    \leq& (1-\beta\mu_g)\sum_{k\in \mathcal{K}_{q,y}}\left\|y_{q}^k-y^*(x_q)^k\right\|^2+\frac{4\beta^2NT(\sigma_{g}^2+\delta_{g}^2)}{\mathcal{C}^{*}_{y}}\nonumber\\&+\frac{2\beta NT(2\beta l_{g,1}-1)}{\mathcal{C}^*} \sum_{k\in \mathcal{K}_{q,y}}\mathbb{E}\left[g(x_q^k,y_{q,t}^k)-g(x_q^k,y^*(x_q)^k)\right]\nonumber
    \nonumber
\end{align}
Let $2\beta l_{g,1}-1\Rightarrow \beta\leq\frac{1}{2l_{g,1}}$ , we can get
\begin{align*}
     \mathbb{E}&\|y_{q+1}-y^*(x_q)\|^2\\ &\leq(1-\beta\mu_g)\mathbb{E}\|y_{q}-y^*(x_q)\|^2+\frac{4NT\beta^2}{\mathcal{C}_y^*}(\sigma_{g}^2+\delta_{g}^2)
\end{align*}
\end{proof}

\begin{lemma}
    Let all assumptions hold, we can bound,
    \begin{align}
&\mathbb{E}\left[\Phi(x_{q+1})\right]-\mathbb{E}\left[\Phi(x_q)\right]\\
&\leq-\frac{\alpha}{2}\sum_{s\in \mathcal{K}_{q,x}}\mathbb{E}\|\nabla \Phi^s(x_{q})\|^2+\frac{\alpha N}{\mathcal{C}_x^*}(2-\alpha+\alpha L_f)\sigma_f^2\nonumber\\
&\quad+\frac{\alpha N}{\mathcal{C}_x^*}(1+L_f)\delta^2_f+\frac{2\alpha N}{\mathcal{C}_x^*}(1-\alpha+\alpha L_f)\mathcal{E}_h\nonumber\\
&\quad+(-\alpha^3+\alpha^3 L_f)\frac{N}{\mathcal{C}_x^*}\sum_{s\in \mathcal{K}_{q,x}}\mathbb{E}\|\nabla f^s(x_{q},y_{q+1})\|^2\nonumber\\
&\quad+2\alpha M_f^2\mathbb{E}\|y_{q+1}-y^*(x_q)\|^2\nonumber
