\begin{proof}
\begin{align*}

    & \mathbb{E}\left[\Phi(x_{q+1})\right]-\mathbb{E}\left[\Phi(x_q)\right] \nonumber\\
    \leq & \mathbb{E}\left[\left\langle x_{q+1} - x_q, \nabla \Phi(x_q) \right\rangle\right] +\frac{L_f}{2} \mathbb{E}\left\|x_{q+1} -x_q\right\|^2\\
    =&\sum_{s\in \mathcal{K}_{q,x}}\mathbb{E}[\langle x_{q+1}^s-x_{q}^s, \nabla \Phi^s(x_{q})\rangle]\nonumber\\
&+\sum_{s\in \mathcal{S}_x-\mathcal{K}_{q,x}}\mathbb{E}[\langle x_{q+1}^s-x_{q}^s,\nabla \Phi^s(x_{q})\rangle]+\frac{L_f}{2} \mathbb{E}\left\|x_{q+1} -x_q\right\|^2\\


    =&\sum_{s\in \mathcal{K}_{q,x}}\mathbb{E}[\langle x_{q+1}^s-x_{q}^s, \nabla \Phi^s(x_{q})\rangle]+\frac{L_f}{2} \sum_{s\in \mathcal{K}_{q,x}}\mathbb{E}\left\|x_{q+1}^s -x_q^s\right\|^2\nonumber\\
&+\frac{L_f}{2}\sum_{s\in \mathcal{S}_x-\mathcal{K}_{q,x}}\mathbb{E}\left\|x_{q+1}^s -x_q^s\right\|^2\\
    =&\sum_{s\in \mathcal{K}_{q,x}} \mathbb{E} \bigg[\Big\langle -\alpha\frac{1}{\mathcal{C}^{s}_{q,x}}\sum_{n\in N_{q,x}^{s}}\nabla f^s_n(x_{q}^n,y_{q+1}^n,\zeta_q^n),\nabla \Phi^s(x_{q})\Big\rangle\bigg]\nonumber\\
&+\frac{L_f}{2} \sum_{s\in \mathcal{K}_{q,x}}\mathbb{E}\left\|x_{q+1}^s -x_q^s\right\|^2\\
    =&(-\frac{1}{2\alpha}+\frac{L_f}{2})\underbrace{\sum_{s\in \mathcal{K}_{q,x}}\mathbb{E}\|x_{q+1}^s -x_q^s\|^2}_{U_1}-\frac{\alpha}{2}\sum_{s\in \mathcal{K}_{q,x}}\mathbb{E}\|\nabla \Phi^s(x_{q})\|^2\\
    &+\underbrace{\frac{\alpha}{2}\sum_{s\in \mathcal{K}_{q,x}}\mathbb{E}\|\frac{1}{\mathcal{C}^{s}_{q,x}}\sum_{n\in N^{s}_{q,x}}\nabla f^s_n(x_{q}^n,y_{q+1}^n,\zeta_q^n)-\nabla \Phi^s(x_{q})\|^2}_{U_2} 
\end{align*}
To bound $U_1$:
\begin{align*}
    &\sum_{s\in \mathcal{K}_{q,x}}\mathbb{E}\|x_{q+1}^s -x_q^s\|^2\\
    =&\sum_{s\in \mathcal{K}_{q,x}}\mathbb{E}\|-\alpha\frac{1}{\mathcal{C}^{s}_{q,x}}\sum_{n\in N_{q,x}^{s}}\nabla f^s_n(x_{q}^n,y_{q+1}^n,\zeta_q^n)\|^2\\
    =&\alpha^2\sum_{s\in \mathcal{K}_{q,x}}\mathbb{E}\|\frac{1}{\mathcal{C}^{s}_{q,x}}\sum_{n\in N^{s}_{q,x}}\nabla f^s_n(x_{q}^n,y_{q+1}^n,\zeta_q^n)\|^2\\
    = &\alpha^2\sum_{s\in \mathcal{K}_{q,x}}\mathbb{E}\|\frac{1}{\mathcal{C}^{s}_{q,x}}\sum_{n\in N^{s}_{q,x}}(\nabla f^s_n(x_{q}^n,y_{q+1}^n,\zeta_q^n)-\nabla f^s_n(x_{q}^n,y_{q+1}^n)\\
    &+\nabla f^s_n(x_{q}^n,y_{q+1}^n)-\nabla f^s_n(x_{q},y_{q+1})+\nabla f^s_n(x_{q},y_{q+1})\\
    &-\nabla f^s(x_{q},y_{q+1})+\nabla f^s(x_{q},y_{q+1}))\|^2 \\


    \leq&4\alpha^2\frac{N}{\mathcal{C}_x^*}\sigma_f^2+4\alpha^2\frac{N}{\mathcal{C}_x^*}\delta^2_f+4\alpha^2\frac{N}{\mathcal{C}_x^*}\mathcal{E}_h\\&+4\alpha^2\frac{N}{\mathcal{C}_x^*}\sum_{s\in \mathcal{K}_{q,x}}\mathbb{E}\|\nabla f^s(x_{q},y_{q+1})\|^2
\end{align*}
To bound $U_2$:
\begin{align*}
    &\frac{\alpha}{2}\sum_{s\in \mathcal{K}_{q,x}}\mathbb{E}\|\frac{1}{\mathcal{C}^{s}_{q,x}}\sum_{n\in N^{s}_{q,x}}\nabla f^s_n(x_{q}^n,y_{q+1}^n,\zeta_q^n)-\nabla \Phi^s(x_{q})\|^2\\




    \leq &2\alpha \frac{N}{\mathcal{C}_x^*}\sigma_f^2+2\alpha\frac{N}{\mathcal{C}_x^*}\mathcal{E}_h+2\alpha\frac{N}{\mathcal{C}_x^*}\delta^2_f\\&+ 2\alpha \sum_{s\in \mathcal{K}_{q,x}}\mathbb{E}\|\nabla f^s(x_{q},y_{q+1})-\nabla \Phi^s(x_{q})\|^2\\
    \leq &2\alpha \frac{N}{\mathcal{C}_x^*}\sigma_f^2+2\alpha\frac{N}{\mathcal{C}_x^*}\mathcal{E}_h+2\alpha\frac{N}{\mathcal{C}_x^*}\delta^2_f+2\alpha M_f^2 \mathbb{E}\|y_{q+1}-y^*(x_q)\|^2
\end{align*}
Thus, we can get
\begin{align*}
&\mathbb{E}\left[\Phi(x_{q+1})\right]-\mathbb{E}\left[\Phi(x_q)\right]
\\\leq&(-\frac{1}{2\alpha}+\frac{L_f}{2})(4\alpha^2\frac{N}{\mathcal{C}_x^*}\sigma_f^2+4\alpha^2\frac{N}{\mathcal{C}_x^*}\delta^2_f+4\alpha^2\frac{N}{\mathcal{C}_x^*}\mathcal{E}_h\\&+4\alpha^2\frac{N}{\mathcal{C}_x^*}\sum_{s\in \mathcal{K}_{q,x}}\mathbb{E}\|\nabla f^s(x_{q},y_{q+1})\|^2)\\
& -\frac{\alpha}{2}\sum_{s\in \mathcal{K}_{q,x}}\mathbb{E}\|\nabla \Phi^s(x_{q})\|^2+2\alpha \frac{N}{\mathcal{C}_x^*}\sigma_f^2+2\alpha\frac{N}{\mathcal{C}_x^*}\mathcal{E}_h\\&+2\alpha\frac{N}{\mathcal{C}_x^*}\delta^2_f+2\alpha M_f^2\mathbb{E}\|y_{q+1}-y^*(x_q)\|^2\\ 
=&-\frac{\alpha}{2}\sum_{s\in \mathcal{K}_{q,x}}\mathbb{E}\|\nabla \Phi^s(x_{q})\|^2+\frac{2L_f\alpha^2 N}{\mathcal{C}_x^*}(\sigma_f^2+\delta^2_f+\mathcal{E}_h)\\
&+(-2\alpha+2 L_f\alpha^2)\frac{N}{\mathcal{C}_x^*}\sum_{s\in \mathcal{K}_{q,x}}\mathbb{E}\|\nabla f^s(x_{q},y_{q+1})\|^2\\&+2\alpha M_f^2\mathbb{E}\|y_{q+1}-y^*(x_q)\|^2
\end{align*}
\end{proof}


