    &+8\alpha^2M_f\frac{N}{\mathcal{C}_x^*}(\sigma_f^2+\delta^2_f+\mathcal{E}_h+\sum_{s\in \mathcal{K}_{q,x}}\mathbb{E}\|\nabla f^s(x_{q},y_{q+1})\|^2)\nonumber\\
    &\leq -\frac{\alpha}{2}\sum_{s\in \mathcal{K}_{q,x}}\mathbb{E}\|\nabla \Phi^s(x_{q})\|^2+\frac{\hat{\alpha}_1 N}{\mathcal{C}_x^*}(\sigma_f^2+\delta^2_f+\mathcal{E}_h)\nonumber\\
    &+(-2\alpha+2 L_f\alpha^2+8\alpha^2M_f)\frac{N}{\mathcal{C}_x^*}\sum_{s\in \mathcal{K}_{q,x}}\mathbb{E}\|\nabla f^s(x_{q},y_{q+1})\|^2\label{eq:lya_a_rabo}\\
    &+(2\alpha M_f^2+2\frac{M_f}{L_y})\mathbb{E}\|y_{q+1}-y^*(x_q)\|^2-\frac{M_f}{L_y}\|y_q-y^*(x_q)\|^2\label{eq:lya_b_rabo}
\end{align}
\end{subequations}
where $\hat{\alpha}_1=2L_f\alpha^2+8M_f\alpha^2$.

It's noticed that Equation~$(\ref{eq:lya_a_rabo})\leq 0$ if $\alpha\leq\frac{1}{L_f+4M_f}$ and we enforce $\alpha$ satisfies it in the following context.

Based on Lemma~\ref{lemma:error_inner}, Equation~(\ref{eq:lya_b_rabo}) can be bounded as
\begin{align}
    &Equation~(\ref{eq:lya_b_rabo})\nonumber\\&\leq(2\alpha M_f^2+2\frac{M_f}{L_y})\nonumber
    \\
    &\quad\cdot((1-\beta\mu_g)\sum_{k\in \mathcal{K}_{q,y}}\left\|y_{q}^k-y^*(x_q)^k\right\|^2 +\frac{4\beta^2NT(\sigma_{g}^2+\delta_{g}^2)}{\mathcal{C}^{*}_{y}})\nonumber
    \\
    &\quad-\frac{M_f}{L_y}\|y_q-y^*(x_q)\|^2
    \nonumber
    \\
    &= \frac{M_f}{L_y}\left((2\alpha L_y M_f+2)(1-\beta \mu_g)-1\right)\sum_{k\in \mathcal{K}_{q,y}}\left\|y_{q}^k-y^*(x_q)^k\right\|^2\nonumber
    \\
    &\quad+(2\alpha M_f^2+2\frac{M_f}{L_y})\frac{4\beta^2NT(\sigma_{g}^2+\delta_{g}^2)}{\mathcal{C}^{*}_{y}}
    \nonumber
\end{align}
If $\beta\leq\frac{1}{\mu_g}$ and $\beta \geq \frac{1}{\mu_g}-\frac{1}{2\alpha L_yM_f\mu_g}$, we can get  
\begin{align*}
\frac{M_f}{L_y}\left((2\alpha L_y M_f+2)(1-\beta \mu_g)-1\right)\leq0
\end{align*}
After rearranging, we can gain that
\begin{align*}
    &\mathbb{E}\| V_{q+1}\|-\mathbb{E}\|V_{q} \|\nonumber\\&\leq-\frac{\alpha}{2}\sum_{s\in \mathcal{K}_{q,x}}\mathbb{E}\|\nabla \Phi^s(x_{q})\|^2+\frac{\hat{\alpha}_1N}{\mathcal{C}_x^*}\sigma_f^2+\frac{\hat{\alpha}_1N}{\mathcal{C}_x^*}\delta^2_f\\
    &\quad+\frac{\hat{\alpha}_1N}{\mathcal{C}_x^*}(2M_f^2 w_1^2 \|x_q\|^2+2M_f^2 w_2^2 \|y_{q+1}\|^2)\\
    &\quad+(2\alpha M_f^2+2\frac{M_f}{L_y})\frac{4\beta^2NT(\sigma_{g}^2+\delta_{g}^2)}{\mathcal{C}^{*}_{y}}
\end{align*}
Summing the above result on $Q$ communication rounds, we can gain that 
\begin{align*}
     &\frac{1}{Q}\sum_{q=1}^Q\sum_{s\in \mathcal{K}_{q,x}}\mathbb{E}\|\nabla \Phi^s(x_{q})\|^2\\&\leq \frac{2\Delta}{\alpha Q}+\frac{2N\hat{\alpha}_1}{\alpha\mathcal{C}_x^*}\sigma_f^2+\frac{2N\hat{\alpha}_1}{\alpha\mathcal{C}_x^*}\delta^2_f\\&\quad+\frac{4N\hat{\alpha}_1}{\alpha\mathcal{C}_x^*}\frac{1}{Q}\sum_{q=1}^Q(M_f^2 w_1^2 \|x_q\|^2+M_f^2 w_2^2 \|y_{q+1}\|^2)\\
     &\quad+(4M_f^2+\frac{4M_f}{\alpha L_y})\frac{4\beta^2NT(\sigma_{g}^2+\delta_{g}^2)}{\mathcal{C}^{*}_{y}}
\end{align*}
where $\Delta=\mathbb{E}\|V_{Q+1}\|-\mathbb{E}\| V_{1}\|$.

Here, we enforce $\alpha\leq \sqrt{\frac{C_x^*}{Q}}$ for some positive $\hat{\alpha}$, and $\beta \leq \frac{1}{NTQ}$, we can get
\begin{align*}
     &\frac{1}{Q}\sum_{q=1}^Q\sum_{s\in \mathcal{K}_{q,x}}\mathbb{E}\|\nabla \Phi^s(x_{q})\|^2\\\leq& \frac{2\Delta}{\sqrt{\mathcal{C}_x^*Q}}+\frac{4N(L_f+4M_f)}{\sqrt{\mathcal{C}_x^*Q}}\sigma_f^2+\frac{4N(L_f+4M_f)}{\sqrt{\mathcal{C}_x^*Q}}\delta^2_f\\&+\frac{8N(L_f+4M_f)}{\sqrt{\mathcal{C}_x^*Q}}\frac{1}{Q}\sum_{q=1}^Q(M_f^2 w_2^2\|x_q\|^2+M_f^2 w_2^2 \|y_{q+1}\|^2)\\

     &+\frac{16M_f^2(\sigma_{g}^2+\delta_{g}^2)}{NTQ^2\mathcal{C}^{*}_{y}}+\frac{16M_f(\sigma_{g}^2+\delta_{g}^2)}{NTQ^{1.5}L_y\sqrt{\mathcal{C}_x^*}\mathcal{C}^{*}_{y}}
\end{align*}
Thus, we can gain 
\begin{align*}
    &\frac{1}{Q}\sum_{q=1}^Q\sum_{s\in \mathcal{K}_{q,x}}\mathbb{E}\|\nabla \Phi^s(x_{q})\|^2\\&\leq \mathcal{O}(\frac{1}{\sqrt{\mathcal{C}_x^*Q}}+\frac{1}{NTQ^2\mathcal{C}^{*}_{y}}+\frac{1}{NTQ^{1.5}\sqrt{\mathcal{C}_x^*}\mathcal{C}^{*}_{y}})
\end{align*}
\end{proof}

\begin{lemma}
    Let all assumptions hold, we can bound,
    \begin{align}
&\mathbb{E}\left[\Phi(x_{q+1})\right]-\mathbb{E}\left[\Phi(x_q)\right]\\
&\leq-\frac{\alpha}{2}\sum_{s\in \mathcal{K}_{q,x}}\mathbb{E}\|\nabla \Phi^s(x_{q})\|^2+\frac{\alpha N}{\mathcal{C}_x^*}(2-\alpha+\alpha L_f)\sigma_f^2\nonumber\\
&\quad+\frac{\alpha N}{\mathcal{C}_x^*}(1+L_f)\delta^2_f+\frac{2\alpha N}{\mathcal{C}_x^*}(1-\alpha+\alpha L_f)\mathcal{E}_h\nonumber\\
&\quad+(-\alpha^3+\alpha^3 L_f)\frac{N}{\mathcal{C}_x^*}\sum_{s\in \mathcal{K}_{q,x}}\mathbb{E}\|\nabla f^s(x_{q},y_{q+1})\|^2\nonumber\\
&\quad+2\alpha M_f^2\mathbb{E}\|y_{q+1}-y^*(x_q)\|^2\nonumber
\end{align}
\end{lemma}
\begin{proof}
\begin{align*}

    & \mathbb{E}\left[\Phi(x_{q+1})\right]-\mathbb{E}\left[\Phi(x_q)\right] \nonumber\\
    \leq & \mathbb{E}\left[\left\langle x_{q+1} - x_q, \nabla \Phi(x_q) \right\rangle\right] +\frac{L_f}{2} \mathbb{E}\left\|x_{q+1} -x_q\right\|^2\\
    =&(-\frac{1}{2\alpha}+\frac{L_f}{2})\underbrace{\sum_{s\in \mathcal{K}_{q,x}}\mathbb{E}\|x_{q+1}^s -x_q^s\|^2}_{U_1'}-\frac{\alpha}{2}\sum_{s\in \mathcal{K}_{q,x}}\mathbb{E}\|\nabla \Phi^s(x_{q})\|^2\\
    &+\underbrace{\frac{\alpha}{2}\sum_{s\in \mathcal{K}_{q,x}}\mathbb{E}\|\frac{1}{\mathcal{C}^{s}_{q,x}}\sum_{n\in N^{s}_{q,x}}\nabla f^s_n(x_{q}^n,y_{q+1}^n,\zeta_q^n)-\nabla \Phi^s(x_{q})\|^2}_{U_2'} 
\end{align*}
To bound $U_1'$:
\begin{align*}
    &\sum_{s\in \mathcal{K}_{q,x}}\mathbb{E}\|x_{q+1}^s -x_q^s\|^2\\
    =&\sum_{s\in \mathcal{K}_{q,x}}\mathbb{E}\|-\alpha\frac{1}{\mathcal{C}^{s}_{q,x}}\sum_{n\in N_{q,x}^{s}}\hat{\nabla} f^s_n(x_{q}^n,y_{q+1}^n,\zeta_q^n)\|^2\\




    \leq&5\alpha^2\frac{N}{\mathcal{C}_x^*}\sigma_{\mathcal{J}}^2+5\alpha^2\frac{N}{\mathcal{C}_x^*}\sigma_f^2+5\alpha^2\frac{N}{\mathcal{C}_x^*}\delta^2_f+5\alpha^2\frac{N}{\mathcal{C}_x^*}\mathcal{E}_h\\&+5\alpha^2\frac{N}{\mathcal{C}_x^*}\sum_{s\in \mathcal{K}_{q,x}}\mathbb{E}\|\nabla f^s(x_{q},y_{q+1})\|^2
\end{align*}
To bound $U_2'$:

\begin{align*}
    &\frac{\alpha}{2}\sum_{s\in \mathcal{K}_{q,x}}\mathbb{E}\|\frac{1}{\mathcal{C}^{s}_{q,x}}\sum_{n\in N^{s}_{q,x}}\nabla f^s_n(x_{q}^n,y_{q+1}^n,\zeta_q^n)-\nabla \Phi^s(x_{q})\|^2\\





    \leq &\frac{5}{2}\alpha \frac{N}{\mathcal{C}_x^*}\sigma_{\mathcal{J}}^2+\frac{5}{2}\alpha \frac{N}{\mathcal{C}_x^*}\sigma_f^2+\frac{5}{2}\alpha\frac{N}{\mathcal{C}_x^*}\mathcal{E}_h+\frac{5}{2}\alpha\frac{N}{\mathcal{C}_x^*}\delta^2_f\\&+\frac{5}{2}\alpha M_f^2 \mathbb{E}\|y_{q+1}-y^*(x_q)\|^2
\end{align*}
Thus, we can get
\begin{align*}
&\mathbb{E}\left[\Phi(x_{q+1})\right]-\mathbb{E}\left[\Phi(x_q)\right]\\
&\leq(-\frac{1}{2\alpha}+\frac{ L_f}{2})(5\alpha^2\frac{N}{\mathcal{C}_x^*}\sigma_{\mathcal{J}}^2+5\alpha^2\frac{N}{\mathcal{C}_x^*}\sigma_f^2+5\alpha^2\frac{N}{\mathcal{C}_x^*}\delta^2_f\\&\quad+5\alpha^2\frac{N}{\mathcal{C}_x^*}\mathcal{E}_h+5\alpha^2\frac{N}{\mathcal{C}_x^*}\sum_{s\in \mathcal{K}_{q,x}}\mathbb{E}\|\nabla f^s(x_{q},y_{q+1})\|^2)\\
&\quad -\frac{\alpha}{2}\sum_{s\in \mathcal{K}_{q,x}}\mathbb{E}\|\nabla \Phi^s(x_{q})\|^2+\frac{5}{2}\alpha \frac{N}{\mathcal{C}_x^*}\sigma_{\mathcal{J}}^2+\frac{5}{2}\alpha \frac{N}{\mathcal{C}_x^*}\sigma_f^2\\&\quad+\frac{5}{2}\alpha\frac{N}{\mathcal{C}_x^*}\mathcal{E}_h+\frac{5}{2}\alpha\frac{N}{\mathcal{C}_x^*}\delta^2_f+\frac{5}{2}\alpha M_f^2 \mathbb{E}\|y_{q+1}-y^*(x_q)\|^2\\ 
&=-\frac{\alpha}{2}\sum_{s\in \mathcal{K}_{q,x}}\mathbb{E}\|\nabla \Phi^s(x_{q})\|^2+\frac{5L_f\alpha^2 N}{2\mathcal{C}_x^*}(\sigma_{\mathcal{J}}^2+\sigma_f^2+\delta^2_f+\mathcal{E}_h)\\
&\quad+(-\frac{5}{2}\alpha+\frac{5}{2} L_f\alpha^2)\frac{N}{\mathcal{C}_x^*}\sum_{s\in \mathcal{K}_{q,x}}\mathbb{E}\|\nabla f^s(x_{q},y_{q+1})\|^2\\&\quad+\frac{5}{2}\alpha M_f^2\mathbb{E}\|y_{q+1}-y^*(x_q)\|^2
\end{align*}
\end{proof}

\begin{lemma}
    Let all assumptions hold, we can gain,
    \begin{align}
    &\mathbb{E}\|y_{q+1}-y^*(x_{q+1})\|^2\\
    \leq&(2-2\beta\mu_g)\mathbb{E}\|y_{q}-y^*(x_q)\|^2+\frac{8NT\beta^2}{\mathcal{C}_y^*}(\sigma_{g}^2+\delta_{g}^2)\nonumber\\
    &+ 10L_y\alpha^2\frac{N}{\mathcal{C}_x^*}\sigma_{\mathcal{J}}^2+10L_y\alpha^2\frac{N}{\mathcal{C}_x^*}\sigma_f^2+10L_y\alpha\frac{N}{\mathcal{C}_x^*}\delta^2_f\nonumber\\
    &+10L_y\alpha^2\frac{N}{\mathcal{C}_x^*}\mathcal{E}_h+10L_y\alpha^3\frac{N}{\mathcal{C}_x^*}\sum_{s\in \mathcal{K}_{q,x}}\mathbb{E}\|\nabla f^s(x_{q},y_{q+1})\|^2\nonumber
    \end{align}
\end{lemma}












\textbf{Proof of Theorem~\ref{convergence2}}
\begin{proof}
We define the following Lyapunov function
\begin{align*}
    V_q:=\Phi(x_q)+\frac{M_f}{L_y}\|y_q-y^*(x_q)\|^2
\end{align*}
The bound of two Lyapunov functions is  
\begin{align*}
    &V_{q+1}-V_{q}\\&=\Phi(x_{q+1})-\Phi(x_q)\\&\quad+\frac{M_f}{L_y}\left( \|y_{q+1}-y^*(x_{q+1})\|^2-\|y_q-y^*(x_q)\|^2\right)
\end{align*}  
From those lemmas, we can get  
\begin{subequations}
\begin{align}
    &\mathbb{E}\| V_{q+1}\|-\mathbb{E}\|V_{q} \|\nonumber\\&\leq-\frac{\alpha}{2}\sum_{s\in \mathcal{K}_{q,x}}\mathbb{E}\|\nabla \Phi^s(x_{q})\|^2+\frac{5L_f\alpha^2 N}{2\mathcal{C}_x^*}(\sigma_{\mathcal{J}}^2+\sigma_f^2+\delta^2_f+\mathcal{E}_h)\nonumber\\
    &+(-\frac{5}{2}\alpha+\frac{5}{2} L_f\alpha^2)\frac{N}{\mathcal{C}_x^*}\sum_{s\in \mathcal{K}_{q,x}}\mathbb{E}\|\nabla f^s(x_{q},y_{q+1})\|^2\nonumber\\
    &+(\frac{5}{2}\alpha M_f^2+2\frac{M_f}{L_y})\mathbb{E}\|y_{q+1}-y^*(x_q)\|^2-\frac{M_f}{L_y}\|y_q-y^*(x_q)\|^2\nonumber\\
    &+10\alpha^2M_f\frac{N}{\mathcal{C}_x^*}\nonumber\\&\quad\cdot(\sigma_{\mathcal{J}}^2+\sigma_f^2+\delta^2_f+\mathcal{E}_h+\sum_{s\in \mathcal{K}_{q,x}}\mathbb{E}\|\nabla f^s(x_{q},y_{q+1})\|^2)\nonumber\\
    &\leq -\frac{\alpha}{2}\sum_{s\in \mathcal{K}_{q,x}}\mathbb{E}\|\nabla \Phi^s(x_{q})\|^2+\frac{\hat{\alpha}_2 N}{\mathcal{C}_x^*}(\sigma_{\mathcal{J}}^2+\sigma_f^2+\delta^2_f+\mathcal{E}_h)\nonumber\\
    &+(-\frac{5}{2}\alpha+\frac{5}{2} L_f\alpha^2+10\alpha^2M_f)\frac{N}{\mathcal{C}_x^*}\sum_{s\in \mathcal{K}_{q,x}}\mathbb{E}\|\nabla f^s(x_{q},y_{q+1})\|^2\label{eq:lya_a}\\
    &+(\frac{5}{2}\alpha M_f^2+2\frac{M_f}{L_y})\mathbb{E}\|y_{q+1}-y^*(x_q)\|^2-\frac{M_f}{L_y}\|y_q-y^*(x_q)\|^2\label{eq:lya_b}
\end{align}
\end{subequations}
where $\hat{\alpha}_2=\frac{5}{2}L_f\alpha^2+10M_f\alpha^2$.

It's noticed that Equation~$(\ref{eq:lya_a})\leq 0$ if $\alpha\leq\frac{1}{L_f+4M_f}$ and we enforce $\alpha$ satisfies it in the following context.

Based on Lemma~\ref{lemma:error_inner}, Equation~(\ref{eq:lya_b}) can be bounded as
\begin{align*}
    &Equation~(\ref{eq:lya_b})\nonumber\\&\leq(2\alpha M_f^2+2\frac{M_f}{L_y})\\&\quad\cdot((1-\beta\mu_g)\sum_{k\in \mathcal{K}_{q,y}}\left\|y_{q}^k-y^*(x_q)^k\right\|^2 +\frac{4\beta^2NT(\sigma_{g}^2+\delta_{g}^2)}{\mathcal{C}^{*}_{y}})\\&\quad-\frac{M_f}{L_y}\|y_q-y^*(x_q)\|^2
    \nonumber
    \\
    &= \frac{M_f}{L_y}\left((2\alpha L_y M_f+2)(1-\beta \mu_g)-1\right)\sum_{k\in \mathcal{K}_{q,y}}\left\|y_{q}^k-y^*(x_q)^k\right\|^2\\&\quad+(2\alpha M_f^2+2\frac{M_f}{L_y})\frac{4\beta^2NT(\sigma_{g}^2+\delta_{g}^2)}{\mathcal{C}^{*}_{y}}
    \nonumber
\end{align*}
If $\beta\leq\frac{1}{\mu_g}$ and $\beta \geq \frac{1}{\mu_g}-\frac{1}{2\alpha L_yM_f\mu_g}$, we can get  
\begin{align*}
\frac{M_f}{L_y}\left((2\alpha L_y M_f+2)(1-\beta \mu_g)-1\right)\leq0
\end{align*}
After rearranging, we can gain that
\begin{align*}
    &\mathbb{E}\| V_{q+1}\|-\mathbb{E}\|V_{q} \|
    \\& \leq-\frac{\alpha}{2}\sum_{s\in \mathcal{K}_{q,x}}\mathbb{E}\|\nabla \Phi^s(x_{q})\|^2+\frac{\hat{\alpha}_2N}{\mathcal{C}_x^*}\sigma_{\mathcal{J}}^2+\frac{\hat{\alpha}_2N}{\mathcal{C}_x^*}\sigma_f^2+\frac{\hat{\alpha}_2N}{\mathcal{C}_x^*}\delta^2_f\\
    &\quad+\frac{\hat{\alpha}_2N}{\mathcal{C}_x^*}(2M_f^2 w_1^2 \|x_q\|^2+2M_f^2 w_2^2 \|y_{q+1}\|^2)\\
    &\quad+(\frac{5}{2}\alpha M_f^2+2\frac{M_f}{L_y})\frac{4\beta^2NT(\sigma_{g}^2+\delta_{g}^2)}{\mathcal{C}^{*}_{y}}
\end{align*}

Summing the result of on $Q$ communication rounds, we can gain that
\begin{align*}
     \frac{1}{Q}&\sum_{q=1}^Q\sum_{s\in \mathcal{K}_{q,x}}\mathbb{E}\|\nabla \Phi^s(x_{q})\|^2\\\leq& \frac{2\Delta}{\alpha Q}+\frac{4N\hat{\alpha}_1}{\alpha\mathcal{C}_x^*}\frac{1}{Q}\sum_{q=1}^Q(M_f^2 w_1^2 \|x_q\|^2+M_f^2 w_2^2 \|y_{q+1}\|^2)\\&+(4M_f^2+\frac{4M_f}{\alpha L_y})\frac{4\beta^2NT(\sigma_{g}^2+\delta_{g}^2)}{\mathcal{C}^{*}_{y}}\\
     &+\frac{2N\hat{\alpha}_1}{\alpha\mathcal{C}_x^*}\sigma_{\mathcal{J}}^2+\frac{2N\hat{\alpha}_1}{\alpha\mathcal{C}_x^*}\sigma_f^2+\frac{2N\hat{\alpha}_1}{\alpha\mathcal{C}_x^*}\delta^2_f
\end{align*}
where $\Delta=\mathbb{E}\|V_{Q+1}\|-\mathbb{E}\| V_{1}\|$.

Here, we enforce $\alpha\leq \sqrt{\frac{C_x^*}{Q}}$ for some positive $\hat{\alpha}$, and $\beta \leq \frac{1}{NTQ}$, we can get
\begin{align*}
     \frac{1}{Q}&\sum_{q=1}^Q\sum_{s\in \mathcal{K}_{q,x}}\mathbb{E}\|\nabla \Phi^s(x_{q})\|^2\\\leq& \frac{2\Delta}{\sqrt{\mathcal{C}_x^*Q}}+\frac{4N(L_f+4M_f)}{\sqrt{\mathcal{C}_x^*Q}}\sigma_{\mathcal{J}}^2+\frac{4N(L_f+4M_f)}{\sqrt{\mathcal{C}_x^*Q}}\sigma_f^2\\&+\frac{4N(L_f+4M_f)}{\sqrt{\mathcal{C}_x^*Q}}\delta^2_f\\&+\frac{8N(L_f+4M_f)}{\sqrt{\mathcal{C}_x^*Q}}\frac{1}{Q}\sum_{q=1}^Q(M_f^2 w_2^2\|x_q\|^2+M_f^2 w_2^2 \|y_{q+1}\|^2)\\
     &+\frac{16M_f^2(\sigma_{g}^2+\delta_{g}^2)}{NTQ^2\mathcal{C}^{*}_{y}}+\frac{16M_f(\sigma_{g}^2+\delta_{g}^2)}{NTQ^{1.5}L_y\sqrt{\mathcal{C}_x^*}\mathcal{C}^{*}_{y}}
\end{align*}
Thus, we can gain 
\begin{align*}
    &\frac{1}{Q}\sum_{q=1}^Q\sum_{s\in \mathcal{K}_{q,x}}\mathbb{E}\|\nabla \Phi^s(x_{q})\|^2\\&\leq \mathcal{O}(\frac{1}{\sqrt{\mathcal{C}_x^*Q}}+\frac{1}{NTQ^2\mathcal{C}^{*}_{y}}+\frac{1}{NTQ^{1.5}\sqrt{\mathcal{C}_x^*}\mathcal{C}^{*}_{y}})
\end{align*}
\end{proof}

In this section, we consider using the bilevel optimization to tune the hyper-parameters in the loss function for learning an imbalanced CIFAR-10~\cite{krizhevsky2009learning} dataset. We tune the VS-loss~\cite{kini2021label} in distributed setting as follows. VS loss is defined as $\mathcal{L}_{VS}(\textbf{x},y)=-w_k\log (e^{\Delta_kf_k(\alpha, y)+l_k}\big/\sum_{c\in[c]}e^{\Delta_cf_c(\alpha, y)+l_c})$, where $\textbf{x}=[\textbf{w}, \textbf{l}, \Delta]$ is the set of hyper parameters, $\alpha$ is the input data, $k$ is the label, $y$ is the parameter of model. Thus we can gain the optimization target as follows,
\begin{center}
\scalebox{0.93}{$
\begin{aligned}
&\min_{\textbf{x}} \Phi(\textbf{x})= 
\frac{1}{n} \sum_{i=1}^n\mathcal{L}_{VS}^{val}(\textbf{x},y^*(\textbf{x})) \nonumber
\\& \;\;\mbox{s.t.} \quad y^*(\textbf{x})\in \arg\min_{y} 
\frac{1}{n}\sum_{i=1}^n\mathcal{L}_{VS}^{tr}(\textbf{x},y).
\end{aligned}
$}
\end{center}
We create imbalanced training and validation datasets by following a long-tail distribution, where the number of examples per class decreases exponentially, that is $n_i'=n_i\mu^i$, where $n_i$ is the original number of examples for class i. We split it into 10 shards as local data. Unlike the few-shot learning task, we employ 80\% training data to train the inner model Resnet18 and 20\% validation data to fine tune the outer hyper parameters on each client. We compare the same baselines as in Section~\ref{sec:few-shot} and set all client capacities $\beta=1/2$.



























\textbf{Performance Evaluation.} The overall performance is shown in Figure~\ref{fig:convergence}. We plot the test accuracy against global iterations to show the convergence and effectiveness of our proposed methods. The horizontal dashed lines serve as full model training baselines: black depicts accuracy reached
by distributed bilevel optimization algorithm FedMBO, and brown depicts accuracy in single-level optimization FedAVG without any loss tuning. Overall, our proposed \textit{RABO} and \textit{RAFBO} achieve state-of-the-art performance compared to baselines. \textit{RABO} improves 9.97\% on average and \textit{RAFBO} improves 5.53\%. In Figure~\ref{fig:cost_tune}, the brown dashed line is the accuracy without tuning the loss function and the black
dashed line is the accuracy with full model bilevel optimization. It's noticed that \textit{RABO} achieves a competitive performance compared to full model training FedAVG without loss tuning. Considering the computation cost, \textit{RABO} achieves $2\times$ reduction and \textit{RAFBO} achieves $4\times$ compared to FedMBO. For communication costs, both of them only take up 25\%. It demonstrates the computation and communication efficiency of our proposed methods.

Distributed bilevel optimization faces the excessive computation challenge when applied in resource-limited clients. In this work, we designed a resource-adaptive efficient distributed bilevel optimization framework \textit{RABO} and based on it we proposed a new hypergradient estimator inspired by finite differences. We theoretically proved both of them can achieve an asymptotically optimal convergence rate $\mathcal{O}(1/\sqrt{\mathcal{C}^*_xQ})$ under the non-convex-strongly-convex condition. Extensive experiments on two tasks confirmed that the effectiveness and computation efficiency of proposed methods.

